#include <bits/stdc++.h>
using namespace std;

long long trailingZeros(long long x) {
    long long result = 0;
    while (x > 0) {
        x /= 5;
        result += x;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;

    long long lo = 0, hi = 5 * n + 5;
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        if (trailingZeros(mid) >= n)
            hi = mid;
        else
            lo = mid + 1;
    }

    if (trailingZeros(lo) != n) {
        cout << 0 << '\n';
    } else {
        cout << 5 << '\n';
        for (long long i = 0; i < 5; ++i)
            cout << lo + i << (i == 4 ? '\n' : ' ');
    }

    return 0;
}

